export const MARCAS = LOGOS;

/** Descobre a marca a partir de uma URL ou de um texto. */
export function marcaDe(alvo = "") {
  const t = String(alvo || "").toLowerCase();
  if (!t) return "";
  for (const [slug, re] of DOMINIOS) if (re.test(t)) return slug;
  for (const [slug, re] of PALAVRAS) if (re.test(t)) return slug;
  return "";
}

/** Logo do serviço, colorido pela marca. */
export function Marca({ slug, size = 14, cor, titulo }) {
  const logo = LOGOS[slug];
  if (!logo) return null;
  return (
    <svg
      width={size} height={size} viewBox="0 0 24 24" role="img" aria-hidden={titulo ? undefined : "true"}
      aria-label={titulo} className={"marca marca-" + slug} style={{ fill: cor || logo.cor, flex: "0 0 auto" }}
    >
      <path d={logo.d} />
    </svg>
  );
}

/** Favicon de verdade do site; se não existir, cai no logo da marca e depois no globo. */
export function FavReal({ url = "", titulo = "", size = 14 }) {
  let host = "";
  try { host = new URL(url).hostname.replace(/^www\./, ""); } catch { host = ""; }
  const slug = marcaDe(url || titulo);
  if (slug) return <Marca slug={slug} size={size} titulo={titulo || slug} />;
  if (!host) return null;
  return (
    <img
      src={`https://icons.duckduckgo.com/ip3/${host}.ico`}
      alt="" width={size} height={size} loading="lazy" referrerPolicy="no-referrer"
      className="fav-real"
      onError={(e) => { e.currentTarget.style.display = "none"; }}
    />
  );
}

export default Marca;
